pub fn real_if_close(arr: Vec<Complex>, tol: i32) -> Vec<Complex> {
    const MACHINE_EPSILON: i32 = 2;
    // Compute the threshold = tol * epsilon, saturating on overflow.
    let threshold = tol.saturating_mul(MACHINE_EPSILON);

    // Check if every imaginary part is within ±threshold.
    let all_close = arr.iter().all(|c| c.imag.abs() <= threshold);

    if all_close {
        // All imag parts are "close to zero": zero them out.
        arr.into_iter()
           .map(|c| Complex { real: c.real, imag: 0 })
           .collect()
    } else {
        // Otherwise, return the original array unchanged.
        arr
    }
}

